<script setup lang="ts">
import {money,localLabel} from '#shared/booking'
const route=useRoute(),error=ref(''),busy=ref(false)
type View={reference:string;startAt:number;endAt:number;date:string;amount:number;name:string;address:string;notes:string;status:string;paymentStatus:string;method:string;holdUntil:number|null;checkoutUrl:string|null;lines:{name:string;quantity:number;price_cents:number}[]}
const {data:booking,error:loadError,refresh}=await useFetch<View>('/api/bookings/'+route.params.token)
useSeoMeta({title:'Tu reserva · Masajes Aurora',robots:'noindex, nofollow'})
const status=computed(()=>({held:'Pendiente de pago',confirmed:'Reserva confirmada',completed:'Sesión realizada',cancelled:'Reserva cancelada',expired:'Reserva no confirmada'}[booking.value?.status||'']||''))
async function pay(){busy.value=true;error.value='';try{const r=await $fetch<{url:string}>('/api/checkout/'+route.params.token,{method:'POST'});window.location.assign(r.url)}catch(e){error.value=apiError(e);await refresh()}finally{busy.value=false}}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{timer=setInterval(()=>{if(booking.value?.status==='held')void refresh()},10000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="page-shell narrow"><header class="page-header"><BrandLogo /></header><main><h1 class="page-title">{{ status||'Tu reserva' }}</h1><p v-if="loadError" class="notice" role="alert">No hemos podido consultar esta reserva. Comprueba el enlace o contacta con Melba.</p><template v-if="booking"><p class="text-muted mb-6">Referencia {{ booking.reference }}</p><div class="surface"><dl class="summary-list"><div><dt>Fecha</dt><dd>{{ booking.date }}</dd></div><div><dt>Horario</dt><dd>{{ localLabel(booking.startAt) }}–{{ localLabel(booking.endAt) }}</dd></div><div v-for="line in booking.lines" :key="line.name"><dt>{{ line.quantity }} · {{ line.name }}</dt><dd>{{ money(line.quantity*line.price_cents) }}</dd></div><div><dt>Total</dt><dd>{{ money(booking.amount) }}</dd></div><div><dt>Pago</dt><dd>{{ booking.paymentStatus==='paid'?'Pagado':booking.paymentStatus==='refunded'?'Reembolsado':booking.paymentStatus==='partial_refund'?'Reembolso parcial':booking.method==='cash'?'En efectivo el día de la cita':'Pendiente' }}</dd></div></dl><p class="mt-5">{{ booking.name }}<br />{{ booking.address }}</p><p v-if="booking.notes" class="mt-3">{{ booking.notes }}</p></div><p v-if="booking.status==='confirmed'" class="mt-6">Hemos preparado el email de confirmación. Si necesitas cambiar o cancelar tu cita, habla con Melba.</p><p v-if="booking.status==='held'" class="notice mt-5">La reserva aún no está confirmada. Completa el pago antes de que finalice el bloqueo temporal.</p><button v-if="booking.status==='held'" class="action mt-5" :disabled="busy" @click="pay">{{ busy?'Comprobando…':'Continuar al pago' }}</button><p v-if="['expired','cancelled'].includes(booking.status)" class="mt-5">Puedes <NuxtLink to="/reservar" class="underline">elegir otra sesión</NuxtLink>.</p><p v-if="error" role="alert" class="notice mt-5">{{ error }}</p><a href="https://wa.me/34644798063" class="text-link mt-8 inline-block">Contactar con Melba</a></template></main></div></template>

